// Standalone repro page for weather-pin flicker: pure deck.gl IconLayer with attribute
// transitions, no MapLibre. See requirements/weather-pin-flicker-debug.md (experiment E3).
import { Deck } from '@deck.gl/core';
import { IconLayer } from '@deck.gl/layers';

const PIN_RADIUS_PX = 13;
const ARROW_TIP_LEN_PX = 10;
const ARROW_WIDTH_PX = 23;
const ICON_W = Math.max(ARROW_WIDTH_PX, PIN_RADIUS_PX * 2);
const ICON_H = ARROW_TIP_LEN_PX + PIN_RADIUS_PX * 2;
const ANCHOR_X = ICON_W / 2;
const ANCHOR_Y = ARROW_TIP_LEN_PX + PIN_RADIUS_PX;
const BASE_HALF_WIDTH = Math.min(ARROW_WIDTH_PX / 2, PIN_RADIUS_PX);
const BASE_Y = ANCHOR_Y - Math.sqrt(PIN_RADIUS_PX ** 2 - BASE_HALF_WIDTH ** 2);

const ICON_MAPPING = {
  arrow: { x: 0, y: 0, width: ICON_W, height: ICON_H, anchorX: ANCHOR_X, anchorY: ANCHOR_Y, mask: true }
};

function buildIconAtlas() {
  const canvas = document.createElement('canvas');
  canvas.width = ICON_W;
  canvas.height = ICON_H;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(ANCHOR_X, ANCHOR_Y, PIN_RADIUS_PX, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(ANCHOR_X, 0);
  ctx.lineTo(ANCHOR_X + BASE_HALF_WIDTH, BASE_Y);
  ctx.lineTo(ANCHOR_X - BASE_HALF_WIDTH, BASE_Y);
  ctx.closePath();
  ctx.fill();
  return canvas;
}

const ICON_ATLAS = buildIconAtlas();

const CENTER = [174.8, -36.85];
const N_PINS = 40;

function makeStations() {
  const stations = [];
  for (let i = 0; i < N_PINS; i++) {
    stations.push({
      id: `s${i}`,
      position: [CENTER[0] + (Math.random() - 0.5) * 0.4, CENTER[1] + (Math.random() - 0.5) * 0.3],
      angle: Math.random() * 360,
      color: [Math.floor(Math.random() * 255), Math.floor(Math.random() * 200), 80, 120]
    });
  }
  return stations;
}

let stations = makeStations();
let useTransitions = true;
let dataVersion = 0;

function makeLayer() {
  return new IconLayer({
    id: 'wx-test-pin',
    data: stations,
    iconAtlas: ICON_ATLAS,
    iconMapping: ICON_MAPPING,
    sizeUnits: 'pixels',
    transitions: useTransitions ? { getAngle: 300, getColor: 300 } : undefined,
    getPosition: d => d.position,
    getIcon: () => 'arrow',
    getSize: ICON_H,
    getAngle: d => d.angle,
    getColor: d => d.color,
    updateTriggers: { getAngle: dataVersion, getColor: dataVersion }
  });
}

const deck = new Deck({
  parent: document.getElementById('deck-container'),
  initialViewState: { longitude: CENTER[0], latitude: CENTER[1], zoom: 10 },
  controller: true,
  layers: [makeLayer()]
});

function redraw() {
  deck.setProps({ layers: [makeLayer()] });
}

let updateTimer = null;

document.getElementById('chk-transitions').addEventListener('change', e => {
  useTransitions = e.target.checked;
  redraw();
});

document.getElementById('chk-updates').addEventListener('change', e => {
  if (e.target.checked) {
    updateTimer = setInterval(() => {
      for (const s of stations) {
        s.angle = (s.angle + 20 + Math.random() * 40) % 360;
        s.color = [Math.floor(Math.random() * 255), Math.floor(Math.random() * 200), 80, 120];
      }
      dataVersion++;
      redraw();
    }, 1000);
  } else {
    clearInterval(updateTimer);
    updateTimer = null;
  }
});

const gl = document.createElement('canvas').getContext('webgl2');
const dbg = gl?.getExtension('WEBGL_debug_renderer_info');
document.getElementById('gl-info').textContent = dbg
  ? gl.getParameter(dbg.UNMASKED_RENDERER_WEBGL)
  : 'renderer info unavailable';
